"""Writes fdtd_bench_colab.ipynb with fdtd_bench.cu embedded, so the notebook
runs on its own (Colab cannot read this private repository).

    python bench/cuda/make_colab_notebook.py
"""
import json
from pathlib import Path

HERE = Path(__file__).parent
source = (HERE / "fdtd_bench.cu").read_text()


def code(text):
    return {"cell_type": "code", "metadata": {}, "execution_count": None, "outputs": [], "source": text}


cells = [
    {"cell_type": "markdown", "metadata": {}, "source": (
        "# NobuRF FDTD kernel benchmark (CUDA)\n\n"
        "Generated by `bench/cuda/make_colab_notebook.py` from `bench/cuda/fdtd_bench.cu`; edit the .cu, not this file.\n\n"
        "1. Runtime > Change runtime type > **T4 GPU**.\n"
        "2. Run all cells. The last one prints the tables (see `bench/README.md`, \"What to look for\").\n")},
    code("!nvidia-smi --query-gpu=name,driver_version,memory.total,clocks.max.memory --format=csv\n!nvcc --version | tail -n 2"),
    code("%%writefile fdtd_bench.cu\n" + source),
    code("!nvcc -O3 -arch=sm_75 -o fdtd_bench fdtd_bench.cu && ./fdtd_bench | tee fdtd_bench_results.txt"),
]
notebook = {
    "cells": cells,
    "metadata": {"accelerator": "GPU", "kernelspec": {"display_name": "Python 3", "name": "python3"}, "colab": {"gpuType": "T4"}},
    "nbformat": 4,
    "nbformat_minor": 5,
}
(HERE / "fdtd_bench_colab.ipynb").write_text(json.dumps(notebook, indent=1) + "\n")
print("wrote", HERE / "fdtd_bench_colab.ipynb")
